package http

import (
	"bytes"
	"fmt"
)

// Response represents an HTTP response
type Response struct {
	StatusCode int               // 200, 404, 500, etc.
	Status     string            // "OK", "Not Found", "Internal Server Error"
	Headers    map[string]string // Header key → value
	Body       []byte            // Response body
}

// StatusText returns the standard HTTP status text
func StatusText(code int) string {
	switch code {
	case 200:
		return "OK"
	case 201:
		return "Created"
	case 204:
		return "No Content"
	case 301:
		return "Moved Permanently"
	case 302:
		return "Found"
	case 304:
		return "Not Modified"
	case 400:
		return "Bad Request"
	case 401:
		return "Unauthorized"
	case 403:
		return "Forbidden"
	case 404:
		return "Not Found"
	case 405:
		return "Method Not Allowed"
	case 500:
		return "Internal Server Error"
	case 501:
		return "Not Implemented"
	case 502:
		return "Bad Gateway"
	case 503:
		return "Service Unavailable"
	default:
		return "Unknown"
	}
}

// NewResponse creates a new Response with default values
func NewResponse(statusCode int) *Response {
	return &Response{
		StatusCode: statusCode,
		Status:     StatusText(statusCode),
		Headers:    make(map[string]string),
		Body:       []byte{},
	}
}

// SetHeader sets a response header
func (r *Response) SetHeader(key, value string) {
	r.Headers[key] = value
}

// SetBody sets the response body
func (r *Response) SetBody(body []byte) {
	r.Body = body
	r.SetHeader("Content-Length", fmt.Sprintf("%d", len(body)))
}

// SetBodyString sets the response body as a string
func (r *Response) SetBodyString(body string) {
	r.SetBody([]byte(body))
}

// Bytes returns the complete HTTP response as bytes
func (r *Response) Bytes() []byte {
	var buf bytes.Buffer

	// Status line: HTTP/1.1 200 OK\r\n
	fmt.Fprintf(&buf, "HTTP/1.1 %d %s\r\n", r.StatusCode, r.Status)

	// Headers
	for key, value := range r.Headers {
		fmt.Fprintf(&buf, "%s: %s\r\n", key, value)
	}

	// Blank line
	buf.WriteString("\r\n")

	// Body
	buf.Write(r.Body)

	return buf.Bytes()
}

// String returns the response as a string (for debugging)
func (r *Response) String() string {
	return string(r.Bytes())
}

