package http

import (
	"bufio"
	"fmt"
	"net"
	"strings"
)

// ParseRequest parses an HTTP request from a connection
// RFC 7230 compliance: Request-line, headers, body
func ParseRequest(conn net.Conn) (*Request, error) {
	reader := bufio.NewReader(conn)

	// Step 1: Parse request line
	// Format: METHOD /path HTTP/1.1\r\n
	line, err := reader.ReadString('\n')
	if err != nil {
		return nil, fmt.Errorf("failed to read request line: %w", err)
	}

	// Remove \r\n
	line = strings.TrimSuffix(line, "\r\n")
	line = strings.TrimSuffix(line, "\n")

	// Parse method, path, version
	parts := strings.Fields(line)
	if len(parts) < 3 {
		return nil, fmt.Errorf("invalid request line: %s", line)
	}

	method := parts[0]
	pathAndQuery := parts[1]
	version := parts[2]

	// Split path and query string
	path := pathAndQuery
	query := ""
	if idx := strings.Index(pathAndQuery, "?"); idx >= 0 {
		path = pathAndQuery[:idx]
		query = pathAndQuery[idx+1:]
	}

	// Step 2: Parse headers
	headers := make(map[string]string)
	for {
		headerLine, err := reader.ReadString('\n')
		if err != nil {
			return nil, fmt.Errorf("failed to read header: %w", err)
		}

		headerLine = strings.TrimSuffix(headerLine, "\r\n")
		headerLine = strings.TrimSuffix(headerLine, "\n")

		// Empty line signals end of headers
		if headerLine == "" {
			break
		}

		// Parse header: Key: Value
		if idx := strings.Index(headerLine, ":"); idx >= 0 {
			key := strings.TrimSpace(headerLine[:idx])
			value := strings.TrimSpace(headerLine[idx+1:])
			headers[key] = value
		}
	}

	// Step 3: Read body based on Content-Length
	body := []byte{}
	if contentLenStr, ok := headers["Content-Length"]; ok {
		contentLen := 0
		for _, ch := range contentLenStr {
			if ch >= '0' && ch <= '9' {
				contentLen = contentLen*10 + int(ch-'0')
			}
		}

		if contentLen > 0 {
			body = make([]byte, contentLen)
			_, err := reader.Read(body)
			if err != nil {
				return nil, fmt.Errorf("failed to read body: %w", err)
			}
		}
	}

	req := &Request{
		Method:  method,
		Path:    path,
		Query:   query,
		Version: version,
		Headers: headers,
		Body:    body,
	}

	return req, nil
}

// ParseRequest reads an HTTP request line
func ParseRequestLine(line string) (method, path, version string, err error) {
	line = strings.TrimSuffix(line, "\r\n")
	line = strings.TrimSuffix(line, "\n")

	parts := strings.Fields(line)
	if len(parts) < 3 {
		err = fmt.Errorf("invalid request line: %s", line)
		return
	}

	method = parts[0]
	path = parts[1]
	version = parts[2]
	return
}

