package tcp

import (
	"fmt"
	"net"
	"sync"
)

// Listener wraps a TCP listener
type Listener struct {
	addr     string
	listener net.Listener
	wg       sync.WaitGroup
	done     chan struct{}
}

// NewListener creates a new TCP listener
func NewListener(addr string) *Listener {
	return &Listener{
		addr: addr,
		done: make(chan struct{}),
	}
}

// Listen starts listening for TCP connections
func (l *Listener) Listen(handler func(conn net.Conn)) error {
	ln, err := net.Listen("tcp", l.addr)
	if err != nil {
		return fmt.Errorf("failed to listen on %s: %w", l.addr, err)
	}

	l.listener = ln
	fmt.Printf("[TCPListener] Listening on %s\n", l.addr)

	// Accept loop
	for {
		select {
		case <-l.done:
			fmt.Println("[TCPListener] Shutting down...")
			return ln.Close()
		default:
		}

		conn, err := ln.Accept()
		if err != nil {
			// Check if we're shutting down
			select {
			case <-l.done:
				return nil
			default:
				fmt.Printf("[TCPListener] Accept error: %v\n", err)
				continue
			}
		}

		// Handle connection in a goroutine
		l.wg.Add(1)
		go func() {
			defer l.wg.Done()
			defer conn.Close()
			handler(conn)
		}()
	}
}

// Stop gracefully shuts down the listener
func (l *Listener) Stop() error {
	close(l.done)
	l.wg.Wait()
	return nil
}

// NumConnections returns the number of active connections (approximate)
func (l *Listener) NumConnections() int {
	// Note: This is approximate since goroutines may be finishing
	return int(l.wg.num)
}

