package main

import (
	"fmt"
	"log"
	"net"
	"os"
	"os/signal"
	"syscall"

	"github.com/kimjindol2025/fl-httpd/internal/http"
	"github.com/kimjindol2025/fl-httpd/internal/router"
	"github.com/kimjindol2025/fl-httpd/internal/tcp"
)

func main() {
	// Default port
	port := ":8080"
	if len(os.Args) > 1 {
		port = os.Args[1]
	}

	// Create router and register handlers
	r := router.NewRouter()

	// Health check endpoint
	r.GET("/health", func(req *http.Request, res *http.Response) {
		res.StatusCode = 200
		res.Status = "OK"
		res.SetBodyString("OK")
	})

	// Root endpoint
	r.GET("/", func(req *http.Request, res *http.Response) {
		res.StatusCode = 200
		res.Status = "OK"
		body := `
<!DOCTYPE html>
<html>
<head>
  <title>FreeLang HTTP Server</title>
  <style>
    body { font-family: monospace; margin: 20px; }
    .code { background: #f0f0f0; padding: 10px; border-radius: 5px; }
  </style>
</head>
<body>
  <h1>🚀 FreeLang HTTP/1.1 Server</h1>
  <p>Zero-Dependency HTTP Server (TCP → RFC 7230)</p>
  <div class="code">
    GET /health → Health check
    GET /api/info → Server info
  </div>
</body>
</html>
`
		res.SetBodyString(body)
		res.SetHeader("Content-Type", "text/html; charset=utf-8")
	})

	// API info endpoint
	r.GET("/api/info", func(req *http.Request, res *http.Response) {
		res.StatusCode = 200
		res.Status = "OK"
		body := `{
  "server": "fl-httpd",
  "version": "1.0.0",
  "status": "running",
  "dependecies": 0,
  "backend": "pure Go stdlib (net, bufio, strings, sync)"
}
`
		res.SetBodyString(body)
		res.SetHeader("Content-Type", "application/json")
	})

	// TCP listener
	listener := tcp.NewListener(port)

	// Handle connections
	connectionHandler := func(conn net.Conn) {
		remoteAddr := conn.RemoteAddr().String()

		// Keep-Alive loop
		for {
			req, err := http.ParseRequest(conn)
			if err != nil {
				log.Printf("[%s] Parse error: %v\n", remoteAddr, err)
				break
			}

			log.Printf("[%s] %s %s %s\n", remoteAddr, req.Method, req.Path, req.Version)

			// Create response
			res := http.NewResponse(200)

			// Route request
			r.Handle(req, res)

			// Set standard headers
			if res.GetHeader("Content-Type") == "" {
				res.SetHeader("Content-Type", "text/plain")
			}

			if req.IsKeepAlive() {
				res.SetHeader("Connection", "keep-alive")
			} else {
				res.SetHeader("Connection", "close")
			}

			// Write response
			_, err = conn.Write(res.Bytes())
			if err != nil {
				log.Printf("[%s] Write error: %v\n", remoteAddr, err)
				break
			}

			// Check if connection should be closed
			if !req.IsKeepAlive() {
				break
			}
		}
	}

	// Start server in a goroutine
	go func() {
		if err := listener.Listen(connectionHandler); err != nil {
			log.Fatalf("Listener error: %v", err)
		}
	}()

	fmt.Printf("✅ Server listening on http://localhost%s\n", port)
	fmt.Printf("   Health: http://localhost%s/health\n", port)
	fmt.Printf("   Info: http://localhost%s/api/info\n", port)

	// Wait for interrupt signal
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)
	<-sigChan

	fmt.Println("\n🛑 Shutting down...")
	listener.Stop()
	fmt.Println("✅ Server stopped")
}

