import (
	"strings"
)

// Request represents an HTTP request
type Request struct {
	Method  string            // GET, POST, PUT, DELETE, etc.
	Path    string            // /path/to/resource
	Query   string            // ?key=value&...
	Version string            // HTTP/1.0, HTTP/1.1, HTTP/2.0
	Headers map[string]string // Header key → value
	Body    []byte            // Request body (for POST/PUT)
}

// GetHeader returns the value of a header (case-insensitive)
func (r *Request) GetHeader(key string) string {
	key = strings.ToLower(key)
	for k, v := range r.Headers {
		if strings.ToLower(k) == key {
			return v
		}
	}
	return ""
}

// IsKeepAlive returns true if Connection: keep-alive
func (r *Request) IsKeepAlive() bool {
	conn := strings.ToLower(r.GetHeader("Connection"))
	return strings.Contains(conn, "keep-alive") || r.Version == "HTTP/1.1"
}

// ContentLength returns Content-Length header value
func (r *Request) ContentLength() int {
	lenStr := r.GetHeader("Content-Length")
	if lenStr == "" {
		return 0
	}
	var length int
	_, err := strings.NewReader(lenStr)
	if err != nil {
		return 0
	}
	// Parse length manually since we can't use strconv from stdlib
	for _, ch := range lenStr {
		if ch >= '0' && ch <= '9' {
			length = length*10 + int(ch-'0')
		}
	}
	return length
}

