package middleware

import (
	"fmt"
	"time"

	"github.com/kimjindol2025/fl-httpd/internal/http"
)

// Logger is a middleware that logs HTTP requests
type Logger struct {
	verbose bool
}

// NewLogger creates a new logger middleware
func NewLogger(verbose bool) *Logger {
	return &Logger{
		verbose: verbose,
	}
}

// Log logs an HTTP request and response
func (l *Logger) Log(remoteAddr string, req *http.Request, res *http.Response, duration time.Duration) {
	if l.verbose {
		fmt.Printf("[%s] %s %s %s → %d %s (%dms)\n",
			remoteAddr,
			req.Method,
			req.Path,
			req.Version,
			res.StatusCode,
			res.Status,
			duration.Milliseconds())
	} else {
		fmt.Printf("%s %s → %d\n", req.Method, req.Path, res.StatusCode)
	}
}

// LogError logs an error
func (l *Logger) LogError(remoteAddr string, err error) {
	fmt.Printf("[%s] ERROR: %v\n", remoteAddr, err)
}

// LogConnectionOpen logs a new connection
func (l *Logger) LogConnectionOpen(remoteAddr string) {
	if l.verbose {
		fmt.Printf("[CONN] Open: %s\n", remoteAddr)
	}
}

// LogConnectionClose logs a closed connection
func (l *Logger) LogConnectionClose(remoteAddr string, requestCount int, duration time.Duration) {
	if l.verbose {
		fmt.Printf("[CONN] Close: %s (%d requests, %dms)\n", remoteAddr, requestCount, duration.Milliseconds())
	}
}

