package compiler

import (
	"fmt"
	"os"
	"os/exec"
	"strings"
	"time"
)

// CompileResult represents the result of a compilation
type CompileResult struct {
	Success   bool          `json:"success"`
	Output    string        `json:"output"`
	Error     string        `json:"error"`
	Duration  time.Duration `json:"duration_ms"`
	BytesUsed int64         `json:"bytes_used"`
}

// FreeLangCompiler manages FreeLang compilation
type FreeLangCompiler struct {
	binPath string
	timeout time.Duration
}

// NewFreeLangCompiler creates a new FreeLang compiler instance
func NewFreeLangCompiler(binPath string) *FreeLangCompiler {
	return &FreeLangCompiler{
		binPath: binPath,
		timeout: 10 * time.Second,
	}
}

// SetTimeout sets the compilation timeout
func (c *FreeLangCompiler) SetTimeout(timeout time.Duration) {
	c.timeout = timeout
}

// IsAvailable checks if FreeLang compiler is available
func (c *FreeLangCompiler) IsAvailable() bool {
	_, err := os.Stat(c.binPath)
	return err == nil
}

// Compile compiles FreeLang code and returns the result
func (c *FreeLangCompiler) Compile(code string) *CompileResult {
	result := &CompileResult{}
	startTime := time.Now()

	// Validate code
	if strings.TrimSpace(code) == "" {
		result.Success = false
		result.Error = "Code cannot be empty"
		result.Duration = time.Since(startTime)
		return result
	}

	// Create temporary file with code
	tmpFile, err := os.CreateTemp("", "freelang_*.fl")
	if err != nil {
		result.Success = false
		result.Error = fmt.Sprintf("Failed to create temp file: %v", err)
		result.Duration = time.Since(startTime)
		return result
	}
	defer os.Remove(tmpFile.Name())

	// Write code to temp file
	if _, err := tmpFile.WriteString(code); err != nil {
		result.Success = false
		result.Error = fmt.Sprintf("Failed to write code: %v", err)
		result.Duration = time.Since(startTime)
		tmpFile.Close()
		return result
	}
	tmpFile.Close()

	// Run compiler with timeout
	ctx, cancel := context.WithTimeout(context.Background(), c.timeout)
	defer cancel()

	cmd := exec.CommandContext(ctx, "node", c.binPath, tmpFile.Name())
	cmd.Env = os.Environ()

	// Capture output
	output, err := cmd.CombinedOutput()
	if err != nil {
		result.Success = false
		result.Error = fmt.Sprintf("Compilation failed: %s", string(output))
	} else {
		result.Success = true
		result.Output = string(output)
	}

	result.Duration = time.Since(startTime)
	result.BytesUsed = int64(len(code))

	return result
}

// CompileAndRun compiles and runs FreeLang code
func (c *FreeLangCompiler) CompileAndRun(code string) *CompileResult {
	result := &CompileResult{}
	startTime := time.Now()

	// For now, just compile
	// TODO: Implement run capability with sandbox
	compileResult := c.Compile(code)
	result.Success = compileResult.Success
	result.Output = compileResult.Output
	result.Error = compileResult.Error
	result.Duration = time.Since(startTime)
	result.BytesUsed = compileResult.BytesUsed

	return result
}

