)

func main() {
	numNodes := flag.Int("nodes", 3, "Number of nodes in the cluster")
	basePort := flag.Int("base-port", 9000, "Base port for cluster nodes")
	flag.Parse()

	fmt.Printf("🚀 Starting Raft cluster with %d nodes (base port %d)\n\n", *numNodes, *basePort)

	// Create nodes
