	}

	for i := 0; i < *numNodes; i++ {
		node := raft.NewRaftNode(int64(i+1), peers)
		nodes[i] = node

		// Log state changes
		fmt.Printf("[Node %d] Started as Follower\n", i+1)

		// Start node
		node.Start()
	}

	// Wait group for graceful shutdown
	var wg sync.WaitGroup

	// Signal handler
	sigChan := make(chan os.Signal, 1)
	signal.Notify(sigChan, syscall.SIGINT, syscall.SIGTERM)

	// Run for a while to see leader election
	go func() {
		time.Sleep(5 * time.Second)
		sigChan <- syscall.SIGINT
	}()

	// Wait for interrupt
	<-sigChan

	fmt.Println("\n🛑 Shutting down cluster...")

	// Stop all nodes
	for i, node := range nodes {
		node.Stop()
		fmt.Printf("[Node %d] Stopped\n", i+1)
	}

	wg.Wait()
	fmt.Println("✅ Cluster stopped")
}

